mapper.sql:
SELECT l.id, l.score_id, l.course_id, c.course_name, l.student_id, st.student_no, st.name AS student_name, l.operator_name, l.operator_role, l.action, l.before_usual_score, l.before_exam_score, l.before_final_score, l.after_usual_score, l.after_exam_score, l.after_final_score, l.remark, l.create_time FROM score_change_log l LEFT JOIN course c ON l.course_id = c.id LEFT JOIN student st ON l.student_id = st.id
AND l.course_id = #{courseId}
AND l.student_id = #{studentId}
ORDER BY l.create_time DESC, l.id DESC
